__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-backend/src"
  cat > "$APP_DIR/core-backend/src/news.ts" << '__COREGSM_EOF__'
/**
 * News: messages written in the panel and posted to a Discord channel by the bot.
 * A news item is a small state machine the bot works through:
 *   draft -> (queued | scheduled) -> sending -> sent        (post)
 *   sent -> edit_queued -> sent                              (edit the posted message)
 *   sent -> delete_queued -> (row removed)                   (delete the posted message)
 */
import express, { type NextFunction, type Request, type RequestHandler, type Response } from 'express';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { z } from 'zod';
import { db, getSetting, setSetting } from './db.js';

const IMG_DIR = path.join(path.dirname(process.env.DB_PATH ?? './data/coregsm.db'), 'news');
fs.mkdirSync(IMG_DIR, { recursive: true });

db.exec(`
CREATE TABLE IF NOT EXISTS news (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  status TEXT NOT NULL,
  channel_id TEXT NOT NULL,
  payload TEXT NOT NULL,
  scheduled_at INTEGER,
  sent_at INTEGER,
  message_id TEXT,
  error TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
`);

try {
  db.exec("ALTER TABLE news ADD COLUMN repeat TEXT NOT NULL DEFAULT 'none'");
} catch {
  /* column already exists */
}

interface NewsRow {
  repeat: string;
  id: number;
  status: string;
  channel_id: string;
  payload: string;
  scheduled_at: number | null;
  sent_at: number | null;
  message_id: string | null;
  error: string | null;
  created_at: number;
  updated_at: number;
}

// ---------- validation (Discord limits) ----------
const link = z
  .string()
  .trim()
  .max(2000)
  .refine((v) => v === '' || /^https?:\/\/\S+$/i.test(v), 'Ссылка должна начинаться с http:// или https://');

const embedSchema = z.object({
  title: z.string().max(256, 'Заголовок: не более 256 символов').optional(),
  url: link.optional(),
  description: z.string().max(4096, 'Текст: не более 4096 символов').optional(),
  color: z.number().int().min(0).max(0xffffff).optional(),
  author: z.object({ name: z.string().max(256), iconUrl: link.optional() }).optional(),
  thumbnailUrl: link.optional(),
  image: z.object({ url: link.optional(), upload: z.string().regex(/^[a-f0-9]{24}\.(png|jpg|gif|webp)$/).optional() }).optional(),
  fields: z
    .array(
      z.object({
        name: z.string().min(1, 'У каждого поля должно быть название').max(256),
        value: z.string().min(1, 'У каждого поля должен быть текст').max(1024, 'Текст поля: не более 1024 символов'),
        inline: z.boolean().optional(),
      }),
    )
    .max(25, 'Полей не больше 25')
    .optional(),
  footer: z.object({ text: z.string().max(2048) }).optional(),
  timestamp: z.boolean().optional(),
});

const payloadSchema = z.object({
  content: z.string().max(2000, 'Сообщение над embed: не более 2000 символов').default(''),
  mention: z.enum(['none', 'here', 'everyone']).default('none'),
  embed: embedSchema.optional(),
});

export type NewsPayload = z.infer<typeof payloadSchema>;

const bodySchema = z.object({
  channelId: z.string().regex(/^\d{15,25}$/, 'Выберите канал для новости'),
  payload: payloadSchema,
  action: z.enum(['draft', 'now', 'schedule']),
  scheduledAt: z.number().int().optional(),
  // a scheduled item can repeat: after it is posted the next one is scheduled
  repeat: z.enum(['none', 'daily', 'weekly', 'monthly']).optional(),
});

/** Drops empty strings, so "no title" is really absent. */
function tidy(p: NewsPayload): NewsPayload {
  const e = p.embed;
  if (!e) return { ...p, embed: undefined };
  const out = { ...e };
  for (const k of ['title', 'url', 'description', 'thumbnailUrl'] as const) if (!out[k]?.trim()) delete out[k];
  if (out.author && !out.author.name.trim()) delete out.author;
  else if (out.author && !out.author.iconUrl) delete out.author.iconUrl;
  if (out.footer && !out.footer.text.trim()) delete out.footer;
  if (out.image && !out.image.url && !out.image.upload) delete out.image;
  else if (out.image && !out.image.url) delete out.image.url;
  if (!out.fields?.length) delete out.fields;
  const hasEmbed = Object.keys(out).some((k) => k !== 'color' && k !== 'timestamp') || (out.timestamp && Object.keys(out).length > 1);
  return { ...p, embed: hasEmbed ? out : undefined };
}

function embedLength(e: NonNullable<NewsPayload['embed']>): number {
  return (
    (e.title?.length ?? 0) +
    (e.description?.length ?? 0) +
    (e.author?.name.length ?? 0) +
    (e.footer?.text.length ?? 0) +
    (e.fields ?? []).reduce((n, f) => n + f.name.length + f.value.length, 0)
  );
}

/** Returns an error message when the payload cannot be posted, otherwise null. */
function check(p: NewsPayload): string | null {
  if (!p.content.trim() && !p.embed) return 'Напишите текст или заполните embed: пустое сообщение отправить нельзя';
  if (p.embed && embedLength(p.embed) > 6000) return 'Embed длиннее 6000 символов (лимит Discord): сократите текст';
  return null;
}

const titleOf = (p: NewsPayload) => p.embed?.title?.trim() || p.content.trim().slice(0, 70) || p.embed?.description?.trim().slice(0, 70) || 'Без названия';

/** the next time a repeating item should go out, always in the future */
function nextOccurrence(from: number, repeat: string, now: number): number {
  const d = new Date(from);
  let guard = 0;
  do {
    if (repeat === 'daily') d.setUTCDate(d.getUTCDate() + 1);
    else if (repeat === 'weekly') d.setUTCDate(d.getUTCDate() + 7);
    else d.setUTCMonth(d.getUTCMonth() + 1);
  } while (d.getTime() <= now && ++guard < 1000);
  return d.getTime();
}

type ChannelInfo = (id: string) => { channelName: string | null; guildName: string | null; guildId: string | null };

export function registerNews(deps: {
  app: express.Express;
  admin: RequestHandler;
  viewer: RequestHandler;
  internal: RequestHandler;
  channelInfo: ChannelInfo;
  isAdmin: (req: Request) => boolean;
}) {
  const { app, admin, viewer, internal, channelInfo, isAdmin } = deps;
  const wrap = (fn: (req: Request, res: Response) => unknown) => (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(fn(req, res)).catch(next);
  };

  const serialize = (r: NewsRow) => {
    const payload = JSON.parse(r.payload) as NewsPayload;
    const ch = channelInfo(r.channel_id);
    return {
      id: r.id,
      status: r.status,
      title: titleOf(payload),
      channelId: r.channel_id,
      channelName: ch.channelName,
      guildName: ch.guildName,
      // a link that opens the posted message in Discord
      messageUrl: r.message_id && ch.guildId ? `https://discord.com/channels/${ch.guildId}/${r.channel_id}/${r.message_id}` : null,
      payload,
      scheduledAt: r.scheduled_at,
      repeat: r.repeat,
      sentAt: r.sent_at,
      error: r.error,
      createdAt: r.created_at,
      updatedAt: r.updated_at,
    };
  };

  // ---------- default news channel ----------
  app.get('/api/news/settings', admin, (_req, res) => {
    const channelId = getSetting('news_channel_id');
    res.json({ channelId, ...(channelId ? channelInfo(channelId) : { channelName: null, guildName: null }) });
  });
  app.put('/api/news/settings', admin, (req, res) => {
    const b = z.object({ channelId: z.string().regex(/^\d{15,25}$/).nullable() }).safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: 'Неверный канал' });
    setSetting('news_channel_id', b.data.channelId);
    res.json({ channelId: b.data.channelId });
  });

  // ---------- images (uploaded in the editor, attached by the bot) ----------
  const EXT: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp' };
  app.post(
    '/api/news/images',
    admin,
    express.raw({ type: Object.keys(EXT), limit: '8mb' }),
    (req, res) => {
      const ext = EXT[String(req.headers['content-type'] ?? '').split(';')[0]];
      if (!ext || !Buffer.isBuffer(req.body) || req.body.length === 0) {
        return res.status(400).json({ error: 'Загрузите картинку PNG, JPG, GIF или WebP до 8 МБ' });
      }
      const name = `${crypto.randomBytes(12).toString('hex')}.${ext}`;
      fs.writeFileSync(path.join(IMG_DIR, name), req.body);
      res.status(201).json({ name, url: `/api/news/images/${name}` });
    },
  );
  // public on purpose (the name is random and unguessable): the panel shows it in <img>
  app.get('/api/news/images/:name', (req, res) => {
    const name = String(req.params.name);
    if (!/^[a-f0-9]{24}\.(png|jpg|gif|webp)$/.test(name)) return res.status(404).end();
    const file = path.join(IMG_DIR, name);
    if (!fs.existsSync(file)) return res.status(404).end();
    res.set('Cache-Control', 'public, max-age=86400').sendFile(file);
  });

  // ---------- CRUD ----------
  /** the public view of a posted news item: no channel ids, errors or schedule */
  const publicNews = (r: NewsRow) => {
    const full = serialize(r);
    return { id: full.id, status: full.status, title: full.title, payload: full.payload, sentAt: full.sentAt };
  };

  app.get('/api/news', viewer, (req, res) => {
    const rows = db.prepare('SELECT * FROM news ORDER BY COALESCE(scheduled_at, sent_at, created_at) DESC, id DESC').all() as NewsRow[];
    if (isAdmin(req)) return res.json(rows.map(serialize));
    res.json(rows.filter((r) => r.status === 'sent' || r.status === 'edit_queued').map(publicNews));
  });

  app.get('/api/news/:id', viewer, (req, res) => {
    const r = db.prepare('SELECT * FROM news WHERE id = ?').get(Number(req.params.id)) as NewsRow | undefined;
    if (!r || (!isAdmin(req) && r.status !== 'sent' && r.status !== 'edit_queued')) return res.status(404).json({ error: 'Новость не найдена' });
    res.json(isAdmin(req) ? serialize(r) : publicNews(r));
  });

  function statusFor(action: 'draft' | 'now' | 'schedule', at: number | undefined): { status: string; at: number | null; error?: string } {
    if (action === 'draft') return { status: 'draft', at: null };
    if (action === 'now') return { status: 'queued', at: null };
    if (!at || at < Date.now() - 60_000) return { status: 'draft', at: null, error: 'Укажите время публикации в будущем' };
    return { status: 'scheduled', at };
  }

  app.post(
    '/api/news',
    admin,
    wrap(async (req, res) => {
      const b = bodySchema.safeParse(req.body);
      if (!b.success) return res.status(400).json({ error: b.error.issues[0]?.message ?? 'Проверьте поля' });
      const payload = tidy(b.data.payload);
      const bad = b.data.action !== 'draft' ? check(payload) : null;
      if (bad) return res.status(400).json({ error: bad });
      const st = statusFor(b.data.action, b.data.scheduledAt);
      if (st.error) return res.status(400).json({ error: st.error });
      const now = Date.now();
      const info = db
        .prepare('INSERT INTO news (status, channel_id, payload, scheduled_at, repeat, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)')
        .run(st.status, b.data.channelId, JSON.stringify(payload), st.at, st.status === 'scheduled' ? (b.data.repeat ?? 'none') : 'none', now, now);
      res.status(201).json(serialize(db.prepare('SELECT * FROM news WHERE id = ?').get(info.lastInsertRowid) as NewsRow));
    }),
  );

  app.put('/api/news/:id', admin, (req, res) => {
    const id = Number(req.params.id);
    const old = db.prepare('SELECT * FROM news WHERE id = ?').get(id) as NewsRow | undefined;
    if (!old) return res.status(404).json({ error: 'Новость не найдена' });
    const b = bodySchema.safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: b.error.issues[0]?.message ?? 'Проверьте поля' });
    const payload = tidy(b.data.payload);
    const now = Date.now();

    if (old.status === 'sent' || old.status === 'edit_queued') {
      // an already posted message: only its content can change, the bot edits the message in place
      const bad = check(payload);
      if (bad) return res.status(400).json({ error: bad });
      db.prepare("UPDATE news SET payload = ?, status = 'edit_queued', error = NULL, updated_at = ? WHERE id = ?").run(JSON.stringify(payload), now, id);
    } else {
      if (['sending', 'delete_queued'].includes(old.status)) return res.status(409).json({ error: 'Новость сейчас отправляется, подождите несколько секунд' });
      const bad = b.data.action !== 'draft' ? check(payload) : null;
      if (bad) return res.status(400).json({ error: bad });
      const st = statusFor(b.data.action, b.data.scheduledAt);
      if (st.error) return res.status(400).json({ error: st.error });
      db.prepare('UPDATE news SET payload = ?, channel_id = ?, status = ?, scheduled_at = ?, repeat = ?, error = NULL, updated_at = ? WHERE id = ?').run(
        JSON.stringify(payload),
        b.data.channelId,
        st.status,
        st.at,
        st.status === 'scheduled' ? (b.data.repeat ?? 'none') : 'none',
        now,
        id,
      );
    }
    res.json(serialize(db.prepare('SELECT * FROM news WHERE id = ?').get(id) as NewsRow));
  });

  // publish a draft / scheduled / failed item right now
  app.post('/api/news/:id/publish', admin, (req, res) => {
    const id = Number(req.params.id);
    const r = db.prepare('SELECT * FROM news WHERE id = ?').get(id) as NewsRow | undefined;
    if (!r) return res.status(404).json({ error: 'Новость не найдена' });
    if (!['draft', 'scheduled', 'error'].includes(r.status)) return res.status(409).json({ error: 'Эта новость уже опубликована или отправляется' });
    const bad = check(JSON.parse(r.payload) as NewsPayload);
    if (bad) return res.status(400).json({ error: bad });
    db.prepare("UPDATE news SET status = 'queued', scheduled_at = NULL, error = NULL, updated_at = ? WHERE id = ?").run(Date.now(), id);
    res.json(serialize(db.prepare('SELECT * FROM news WHERE id = ?').get(id) as NewsRow));
  });

  app.delete('/api/news/:id', admin, (req, res) => {
    const id = Number(req.params.id);
    const r = db.prepare('SELECT * FROM news WHERE id = ?').get(id) as NewsRow | undefined;
    if (!r) return res.status(404).json({ error: 'Новость не найдена' });
    if (r.message_id && (r.status === 'sent' || r.status === 'edit_queued')) {
      // also remove the message from Discord; the row disappears once the bot confirms
      db.prepare("UPDATE news SET status = 'delete_queued', updated_at = ? WHERE id = ?").run(Date.now(), id);
      return res.json({ ok: true, pending: true });
    }
    db.prepare('DELETE FROM news WHERE id = ?').run(id);
    res.json({ ok: true });
  });

  // ---------- internal: the bot ----------
  app.get('/internal/news/pending', internal, (_req, res) => {
    const now = Date.now();
    const rows = db
      .prepare(
        `SELECT * FROM news WHERE status IN ('queued','edit_queued','delete_queued')
           OR (status = 'scheduled' AND scheduled_at <= ?)
           OR (status = 'sending' AND updated_at < ?)`,
      )
      .all(now, now - 5 * 60_000) as NewsRow[];
    const claim = db.prepare("UPDATE news SET status = 'sending', updated_at = ? WHERE id = ?");
    const out = rows.map((r) => {
      const action = r.status === 'edit_queued' ? 'edit' : r.status === 'delete_queued' ? 'delete' : 'send';
      // claim sends so a slow bot cannot post the same news twice
      if (action === 'send') claim.run(now, r.id);
      return { id: r.id, action, channelId: r.channel_id, messageId: r.message_id, payload: JSON.parse(r.payload) as NewsPayload };
    });
    res.json(out);
  });

  app.patch('/internal/news/:id', internal, (req, res) => {
    const b = z
      .object({
        status: z.enum(['sent', 'error', 'deleted']),
        messageId: z.string().max(40).nullable().optional(),
        error: z.string().max(300).nullable().optional(),
      })
      .safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: 'bad body' });
    const id = Number(req.params.id);
    const now = Date.now();
    if (b.data.status === 'deleted') {
      db.prepare('DELETE FROM news WHERE id = ?').run(id);
    } else if (b.data.status === 'sent') {
      const prev = db.prepare('SELECT * FROM news WHERE id = ?').get(id) as NewsRow | undefined;
      // the first successful post of a repeating item schedules the next one
      if (prev && prev.repeat !== 'none' && !prev.sent_at && prev.scheduled_at) {
        const next = nextOccurrence(prev.scheduled_at, prev.repeat, now);
        db.prepare("INSERT INTO news (status, channel_id, payload, scheduled_at, repeat, created_at, updated_at) VALUES ('scheduled', ?, ?, ?, ?, ?, ?)").run(prev.channel_id, prev.payload, next, prev.repeat, now, now);
      }
      db.prepare("UPDATE news SET status = 'sent', message_id = COALESCE(?, message_id), sent_at = COALESCE(sent_at, ?), error = ?, updated_at = ? WHERE id = ?").run(
        b.data.messageId ?? null,
        now,
        b.data.error ?? null,
        now,
        id,
      );
    } else {
      // a failed edit/delete keeps the posted message ("sent"), a failed post becomes "error"
      const row = db.prepare('SELECT message_id FROM news WHERE id = ?').get(id) as { message_id: string | null } | undefined;
      db.prepare('UPDATE news SET status = ?, error = ?, updated_at = ? WHERE id = ?').run(row?.message_id ? 'sent' : 'error', b.data.error ?? 'Ошибка отправки', now, id);
    }
    res.json({ ok: true });
  });
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-backend/src"
  cat > "$APP_DIR/core-backend/src/ops.ts" << '__COREGSM_EOF__'
/**
 * Operations for administrators: action log, bulk actions on Discord bindings,
 * system health and diagnostics, database backup and restore.
 */
import express, { type Express, type NextFunction, type Request, type RequestHandler, type Response } from 'express';
import Database from 'better-sqlite3';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { z } from 'zod';
import { db, getSetting } from './db.js';

const DB_PATH = process.env.DB_PATH ?? './data/coregsm.db';
const DATA_DIR = path.dirname(DB_PATH);
const startedAt = Date.now();

// ---------- action log ----------
interface Rule {
  m: string;
  re: RegExp;
  label: string;
  /** looked up before the handler runs (a deleted row can no longer be read afterwards) */
  pre?: (id: string) => string | null;
  detail?: (req: Request, pre: string | null) => string;
  /** the user is not signed in yet: take the name from the body */
  anon?: boolean;
}

const nameOf = (sql: string) => (id: string) => (db.prepare(sql).get(Number(id)) as { n: string } | undefined)?.n ?? null;
const serverName = nameOf("SELECT COALESCE(NULLIF(name, ''), host || ':' || port) AS n FROM servers WHERE id = ?");
const userName = nameOf('SELECT username AS n FROM users WHERE id = ?');
const s = (v: unknown, n = 80) => (typeof v === 'string' ? v.slice(0, n) : '');

const RULES: Rule[] = [
  { m: 'POST', re: /^\/api\/servers$/, label: 'Добавлен сервер', detail: (r) => s(r.body?.name) || `${s(r.body?.host)}:${Number(r.body?.port) || ''}` },
  { m: 'PUT', re: /^\/api\/servers\/(\d+)$/, label: 'Изменён сервер', pre: serverName },
  { m: 'DELETE', re: /^\/api\/servers\/(\d+)$/, label: 'Удалён сервер', pre: serverName },
  { m: 'POST', re: /^\/api\/bindings$/, label: 'Создана привязка Discord', detail: (r) => `сервер #${Number(r.body?.serverId) || '?'}` },
  { m: 'PUT', re: /^\/api\/bindings\/(\d+)$/, label: 'Изменена привязка Discord', pre: (id) => `#${id}` },
  { m: 'DELETE', re: /^\/api\/bindings\/(\d+)$/, label: 'Удалена привязка Discord', pre: (id) => `#${id}` },
  { m: 'POST', re: /^\/api\/bindings\/bulk$/, label: 'Массовое действие с привязками', detail: (r) => `${s(r.body?.action, 12)} × ${Array.isArray(r.body?.ids) ? r.body.ids.length : 0}` },
  { m: 'PUT', re: /^\/api\/settings$/, label: 'Изменены настройки бота', detail: (r) => [r.body?.discordToken !== undefined ? 'токен' : '', r.body?.proxyUrl !== undefined ? 'прокси' : ''].filter(Boolean).join(', ') },
  { m: 'POST', re: /^\/api\/news$/, label: 'Создана новость', detail: (r) => s(r.body?.payload?.embed?.title) || s(r.body?.payload?.content, 60) },
  { m: 'PUT', re: /^\/api\/news\/(\d+)$/, label: 'Изменена новость', pre: (id) => `#${id}` },
  { m: 'POST', re: /^\/api\/news\/(\d+)\/publish$/, label: 'Новость отправлена в Discord', pre: (id) => `#${id}` },
  { m: 'DELETE', re: /^\/api\/news\/(\d+)$/, label: 'Удалена новость', pre: (id) => `#${id}` },
  { m: 'PUT', re: /^\/api\/news\/settings$/, label: 'Изменён канал новостей' },
  { m: 'PUT', re: /^\/api\/users\/(\d+)$/, label: 'Изменена роль пользователя', pre: userName, detail: (r, p) => `${p ?? ''} → ${s(r.body?.role, 10)}` },
  { m: 'PUT', re: /^\/api\/users\/(\d+)\/password$/, label: 'Сброшен пароль пользователя', pre: userName },
  { m: 'DELETE', re: /^\/api\/users\/(\d+)$/, label: 'Удалён пользователь', pre: userName },
  { m: 'PUT', re: /^\/api\/access$/, label: 'Изменён доступ к панели', detail: (r) => [r.body?.publicPanel !== undefined ? `открыта: ${r.body.publicPanel ? 'да' : 'нет'}` : '', r.body?.registration !== undefined ? `регистрация: ${r.body.registration ? 'да' : 'нет'}` : ''].filter(Boolean).join(', ') },
  { m: 'PUT', re: /^\/api\/branding$/, label: 'Изменено оформление', detail: (r) => s(r.body?.name, 32) },
  { m: 'PUT', re: /^\/api\/branding\/logo$/, label: 'Загружен логотип' },
  { m: 'DELETE', re: /^\/api\/branding\/logo$/, label: 'Сброшен логотип' },
  { m: 'POST', re: /^\/api\/update\/apply$/, label: 'Запущено обновление панели' },
  { m: 'POST', re: /^\/api\/backup\/restore$/, label: 'Восстановлена резервная копия' },
  { m: 'POST', re: /^\/api\/auth\/login$/, label: 'Вход', anon: true },
  { m: 'POST', re: /^\/api\/auth\/register$/, label: 'Регистрация', anon: true },
  { m: 'POST', re: /^\/api\/auth\/password$/, label: 'Смена пароля' },
  { m: 'POST', re: /^\/api\/users\/(\d+)\/approve$/, label: 'Одобрена заявка на регистрацию', pre: userName },
  { m: 'POST', re: /^\/api\/sessions\/revoke-others$/, label: 'Завершены остальные сеансы' },
  { m: 'PUT', re: /^\/api\/alerts$/, label: 'Изменены оповещения о недоступности серверов' },
  { m: 'POST', re: /^\/api\/alerts\/test$/, label: 'Тестовое оповещение' },
];

/** records every successful change made through the panel; must be installed before the routes */
export function installAudit(app: Express): void {
  const insert = db.prepare('INSERT INTO audit (ts, actor, action, detail) VALUES (?, ?, ?, ?)');
  app.use('/api', (req: Request, res: Response, next: NextFunction) => {
    if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') return next();
    const url = req.originalUrl.split('?')[0];
    let match: RegExpExecArray | null = null;
    const rule = RULES.find((r) => r.m === req.method && (match = r.re.exec(url)) !== null);
    if (!rule || !match) return next();
    const id = (match as RegExpExecArray)[1] ?? '';
    const pre = rule.pre ? rule.pre(id) : null;
    res.on('finish', () => {
      if (res.statusCode >= 400) return;
      try {
        const user = (req as Request & { user?: { username: string } }).user;
        const actor = user?.username ?? (rule.anon ? s(req.body?.username, 40) : '') ?? '';
        const detail = rule.detail ? rule.detail(req, pre) : (pre ?? '');
        insert.run(Date.now(), actor || '—', rule.label, detail.trim());
        db.prepare('DELETE FROM audit WHERE id <= (SELECT MAX(id) - 2000 FROM audit)').run();
      } catch (e) {
        console.error('audit failed', (e as Error).message);
      }
    });
    next();
  });
}

interface Ctx {
  app: Express;
  admin: RequestHandler;
  getBot: () => { state: string; tag: string | null; error: string | null; updatedAt: number };
  guildCount: () => number;
  version: string;
  pollMs: number;
}

export function registerOps({ app, admin, getBot, guildCount, version, pollMs }: Ctx): void {
  // ----- log -----
  app.get('/api/audit', admin, (req, res) => {
    const limit = Math.min(500, Math.max(1, Number(req.query.limit) || 200));
    res.json(db.prepare('SELECT id, ts, actor, action, detail FROM audit ORDER BY id DESC LIMIT ?').all(limit));
  });

  // ----- bulk actions on bindings -----
  app.post('/api/bindings/bulk', admin, (req, res) => {
    const b = z
      .object({ ids: z.array(z.number().int()).min(1).max(500), action: z.enum(['pause', 'resume', 'delete']) })
      .safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: 'Выберите привязки и действие' });
    const marks = b.data.ids.map(() => '?').join(',');
    const r =
      b.data.action === 'delete'
        ? db.prepare(`DELETE FROM bindings WHERE id IN (${marks})`).run(...b.data.ids)
        : db.prepare(`UPDATE bindings SET enabled = ? WHERE id IN (${marks})`).run(b.data.action === 'resume' ? 1 : 0, ...b.data.ids);
    res.json({ changed: r.changes });
  });

  // ----- health -----
  const freeSpace = () => {
    try {
      const st = fs.statfsSync(DATA_DIR);
      return { free: Number(st.bavail) * Number(st.bsize), total: Number(st.blocks) * Number(st.bsize) };
    } catch {
      return { free: null, total: null };
    }
  };
  const count = (sql: string) => (db.prepare(sql).get() as { c: number }).c;

  app.get('/api/system', admin, (_req, res) => {
    const space = freeSpace();
    const dbBytes = (() => {
      try {
        return fs.statSync(DB_PATH).size;
      } catch {
        return null;
      }
    })();
    res.json({
      version: version || null,
      uptimeSec: Math.round((Date.now() - startedAt) / 1000),
      node: process.version,
      dbBytes,
      diskFree: space.free,
      diskTotal: space.total,
      memoryMb: Math.round(process.memoryUsage().rss / 1048576),
      counts: {
        servers: count('SELECT COUNT(*) AS c FROM servers'),
        online: count('SELECT COUNT(*) AS c FROM status WHERE online = 1'),
        bindings: count('SELECT COUNT(*) AS c FROM bindings'),
        users: count('SELECT COUNT(*) AS c FROM users'),
        history: count('SELECT COUNT(*) AS c FROM history'),
      },
      bot: getBot(),
      guilds: guildCount(),
      publicBase: getSetting('public_base') || null,
    });
  });

  type Check = { id: string; label: string; status: 'ok' | 'warn' | 'fail'; detail: string };
  const probe = async (url: string): Promise<boolean> => {
    try {
      const r = await fetch(url, { signal: AbortSignal.timeout(6000), headers: { 'User-Agent': 'CoreGSM' } });
      return r.status < 500;
    } catch {
      return false;
    }
  };

  app.post('/api/system/run', admin, async (_req, res) => {
    const checks: Check[] = [];
    const add = (id: string, label: string, status: Check['status'], detail: string) => checks.push({ id, label, status, detail });

    try {
      const q = db.pragma('quick_check', { simple: true });
      add('db', 'База данных', q === 'ok' ? 'ok' : 'fail', q === 'ok' ? 'Целостность в порядке' : `Проверка вернула: ${String(q)}`);
    } catch (e) {
      add('db', 'База данных', 'fail', (e as Error).message);
    }

    const sp = freeSpace();
    if (sp.free == null) add('disk', 'Место на диске', 'warn', 'Не удалось определить');
    else {
      const gb = (sp.free / 1073741824).toFixed(1);
      add('disk', 'Место на диске', sp.free < 300 * 1048576 ? 'fail' : sp.free < 1073741824 ? 'warn' : 'ok', `Свободно ${gb} ГБ`);
    }

    const bot = getBot();
    const tokenSet = !!getSetting('discord_token');
    if (!tokenSet) add('token', 'Токен Discord-бота', 'warn', 'Не задан: Настройки → Discord-бот');
    else add('token', 'Токен Discord-бота', 'ok', 'Задан');
    if (tokenSet) {
      const stale = Date.now() - bot.updatedAt > 45_000;
      if (stale) add('bot', 'Discord-бот', 'fail', 'Не отвечает. На сервере: sudo coregsm logs bot');
      else if (bot.state === 'online') add('bot', 'Discord-бот', 'ok', `Подключён${bot.tag ? ` как ${bot.tag}` : ''}`);
      else add('bot', 'Discord-бот', bot.state === 'error' ? 'fail' : 'warn', bot.error ?? `Состояние: ${bot.state}`);
      const g = guildCount();
      add('guilds', 'Серверы Discord, где есть бот', g > 0 ? 'ok' : 'warn', g > 0 ? `Найдено: ${g}` : 'Бот пока нигде не добавлен: используйте кнопку приглашения');
    }

    const last = (db.prepare('SELECT MAX(updated_at) AS t FROM status').get() as { t: number | null }).t;
    const total = count('SELECT COUNT(*) AS c FROM servers');
    if (total === 0) add('poll', 'Опрос игровых серверов', 'warn', 'Серверов ещё нет');
    else if (!last || Date.now() - last > Math.max(pollMs * 5, 120_000)) add('poll', 'Опрос игровых серверов', 'fail', 'Давно не было ответов: проверьте журнал backend');
    else add('poll', 'Опрос игровых серверов', 'ok', `Последний опрос ${Math.round((Date.now() - last) / 1000)} с назад`);

    const base = getSetting('public_base');
    add('public', 'Публичный адрес (значки в Discord)', base ? 'ok' : 'warn', base ? base : 'Откройте панель по домену с https, и значки игр появятся в сообщениях');

    const [gh, ds] = await Promise.all([probe('https://api.github.com'), getSetting('proxy_url') ? Promise.resolve(true) : probe('https://discord.com/api/v10/gateway')]);
    add('github', 'Доступ к GitHub (обновления)', gh ? 'ok' : 'warn', gh ? 'Доступен' : 'Нет ответа: проверка обновлений не сработает');
    add('discord-net', 'Доступ к Discord', ds ? 'ok' : 'fail', getSetting('proxy_url') ? 'Работа идёт через прокси' : ds ? 'Доступен напрямую' : 'Нет ответа. Включите прокси в настройках бота');
    res.json({ at: Date.now(), checks });
  });

  // ----- backup -----
  app.get('/api/backup', admin, async (_req, res) => {
    const tmp = path.join(os.tmpdir(), `coregsm-backup-${Date.now()}.db`);
    try {
      await db.backup(tmp);
    } catch (e) {
      return res.status(500).json({ error: `Не удалось создать копию: ${(e as Error).message}` });
    }
    const d = new Date();
    const p = (n: number) => String(n).padStart(2, '0');
    const name = `coregsm-backup-${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}.db`;
    res.download(tmp, name, () => fs.rmSync(tmp, { force: true }));
  });

  app.post('/api/backup/restore', admin, express.raw({ type: 'application/octet-stream', limit: '300mb' }), (req, res) => {
    const body = req.body as Buffer;
    if (!Buffer.isBuffer(body) || body.length < 4096 || body.subarray(0, 15).toString('latin1') !== 'SQLite format 3') {
      return res.status(400).json({ error: 'Это не файл резервной копии CoreGSM (.db)' });
    }
    const pending = path.join(DATA_DIR, 'restore-pending.db');
    try {
      fs.writeFileSync(pending, body);
      const t = new Database(pending, { readonly: true });
      const tables = (t.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all() as { name: string }[]).map((x) => x.name);
      const ok = ['users', 'servers', 'settings'].every((n) => tables.includes(n)) && t.pragma('quick_check', { simple: true }) === 'ok';
      t.close();
      for (const ext of ['-wal', '-shm']) fs.rmSync(`${pending}${ext}`, { force: true });
      if (!ok) throw new Error('bad');
    } catch {
      fs.rmSync(pending, { force: true });
      return res.status(400).json({ error: 'Файл повреждён или это копия не от CoreGSM' });
    }
    // the swap happens at start-up (see db.ts); the container restarts by itself
    res.json({ ok: true, restarting: true });
    setTimeout(() => process.exit(0), 800);
  });
}
